INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1531481-math441', 'stk-omar4', 'MATH 441', 'info', '{"desc": "Math441 - Advanced Calculus II\nسابقًا 411\nTerm 202\n\nجودة المقرر بشكل عام :\nيعتبر المقرر أساس رياضي مهم لطالب الرياضيات يتمثل في التحليل الحقيقي ويعتبر امتداد ل Math341.\nيبين ويوضح ويثبت نظريات ومبرهنات التفاضل والتكامل في عدة متغيرات.\n\nالمواضيع التي يغطيها المقرر :\nيبدأ المقرر بالفضاء الاقليدي (Euclidean space R^n).\nثم ينتقل لدراسة فضاء R^n كفضاء متري (R^n as a metric space).\nثم ينتقل لدراسة المتتابعات والمتسلسلات في R^n وأهم النظريات عليها (Series and Sequences in R^n).\nثم ينتقل إلى الدوال من عدة متغيرات والنهايات والاتصال عليها (Functions in R^n, Limits and Continuity).\nثم ينتقل للمشتقة ونظرية القيمة المتوسطة ومتسلسلة تايلر وأهم النظريات والاشتقاق الجزئي باستخدام التحويلات الخطية (Linear Transformations, Continuous Functions on Compact Sets, Differentiable Functions, Partial and Directional Derivatives, The Mean Value Theorem, Higher Order Derivatives, Taylor’s Theorem, Minima and Maxima, The Inverse and Implicit Function Theorems, and Lagrange’s Multipliers ).\nثم ينتقل للتكامل وخصائصه (Integral in R^n, Integrals over Bounded Sets, Properties of Multiple Integrals, Iterated Integrals, Fubini’s Theorem, Change of Variables, Convergence and Divergence of Improper Integrals, Differentiation Under the Integral Sign).\nتجد الSyllabus في موقع قسم الرياضيات.\n\nالكتاب المستخدم للمقرر :\n“Functions of Several Real Variables” by M. Moskowitz and F. Paliogiannis, World Scientific, Singapore, 2011\nالكتاب جيد ويحتوي على أمثلة جيدة وسرد الكتاب جيد وبعض الصفحات فيها أخطاء كتابية.\n\nتعتبر الكتب التالية مراجع جيدة لدراسة المقرر :\nAnalysis II by Terence Tao\nPrinciples of Mathematical Analysis by Walter Rudin\nAnalysis on Manifolds by James Munkres\nCalculus on Manifolds : A Modern Approach to Classical Theorems of Advanced Calculus by Michael Spivak\nمبادئ التحليل الحقيقي الجزء الثاني - د.محمد القويز و د.صالح السنوسي\n\nالأسئلة والأمثلة المستخدمة في المقرر :\nالأسئلة بالكتاب جيدة وتركز على أفكار كل درس , وقد تستخدم مراجع أخرى للبحث عن أسئلة إضافية لكثرة الأفكار.\n\nمدى فائدته في الناحية التطبيقية :\nيكمل المقرر الجزء النظري من Math341 لعدة متغيرات ويعتبر مقدمة لمواضيع متقدمة في التحليل الدالي ونظرية التكامل والتحليل الحقيقي المتقدم, يحتوي على تطبيقات رياضية فقط وتركيزه على الاثباتات.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-441-advanced-calculus-ii/184159/1", "user": "OMAR4", "ts": 1629946465000, "tid": 184159, "pn": 1}}', 1629946465000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
